<?php declare(strict_types=1); $e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8'); $appName=getenv('APP_NAME')?:'Academic Timetable Optimiser'; ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Academic calendar · <?= $e($appName) ?></title><script src="https://cdn.tailwindcss.com"></script></head><body class="min-h-screen bg-slate-50 text-slate-900"><div class="min-h-screen lg:flex"><aside class="bg-slate-950 text-white lg:w-64"><div class="border-b border-white/10 px-6 py-6"><p class="text-xs uppercase tracking-widest text-cyan-300">Academic planning</p><a href="/" class="mt-2 block text-lg font-semibold"><?= $e($appName) ?></a></div><nav class="flex flex-wrap gap-2 p-4 lg:flex-col"><a class="rounded-lg px-3 py-2 text-sm text-slate-300" href="/">Overview</a><a class="rounded-lg px-3 py-2 text-sm text-slate-300" href="/teachers">Teachers</a><a class="rounded-lg px-3 py-2 text-sm text-slate-300" href="/demand">Courses & units</a><a aria-current="page" class="rounded-lg bg-white/10 px-3 py-2 text-sm" href="/calendar">Academic calendar</a><a class="rounded-lg px-3 py-2 text-sm text-slate-300" href="/rules">Protected blocks</a></nav></aside><main class="min-w-0 flex-1"><header class="border-b bg-white px-6 py-5 lg:px-10"><p class="text-sm text-slate-500">Delivery date boundaries</p><h1 class="text-2xl font-semibold">Academic calendar</h1><p class="mt-1 text-sm text-slate-600">Teaching dates are bounded by academic years and terms; bank holidays are recorded as non-teaching dates.</p></header><div class="mx-auto max-w-7xl space-y-6 px-6 py-8 lg:px-10">
<?php if($flash): ?><div role="status" class="rounded-xl border p-4 text-sm <?= $flash['type']==='success'?'border-emerald-200 bg-emerald-50':'border-rose-200 bg-rose-50' ?>"><?= $e($flash['message']) ?></div><?php endif; ?>
<div class="grid gap-6 xl:grid-cols-3"><section class="rounded-xl border bg-white p-5"><h2 class="font-semibold">Academic years</h2><form method="post" action="/calendar/year" class="mt-4 space-y-3"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><label class="block text-sm">Name<input required name="name" maxlength="80" placeholder="2026/27" class="mt-1 block w-full rounded-lg border px-3 py-2"></label><div class="grid grid-cols-2 gap-3"><label class="text-sm">Starts<input required type="date" name="starts_on" class="mt-1 block w-full rounded-lg border px-2 py-2"></label><label class="text-sm">Ends<input required type="date" name="ends_on" class="mt-1 block w-full rounded-lg border px-2 py-2"></label></div><label class="flex gap-2 text-sm"><input type="checkbox" name="is_active" checked>Active year</label><button class="rounded-lg bg-cyan-700 px-4 py-2 text-sm font-semibold text-white">Add year</button></form><div class="mt-5 space-y-2"><?php foreach($years as $y): ?><div class="flex justify-between border-t pt-2 text-sm"><span class="font-medium"><?= $e($y['name']) ?><?= (int)$y['is_active']?'':' · inactive' ?></span><span class="text-slate-500"><?= $e($y['starts_on']) ?> – <?= $e($y['ends_on']) ?></span></div><?php endforeach; ?></div></section>
<section class="rounded-xl border bg-white p-5"><h2 class="font-semibold">Terms</h2><form method="post" action="/calendar/term" class="mt-4 space-y-3"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><label class="block text-sm">Academic year<select required name="academic_year_id" class="mt-1 block w-full rounded-lg border px-3 py-2"><option value="">Choose year</option><?php foreach($years as $y): ?><option value="<?= (int)$y['id'] ?>"><?= $e($y['name']) ?> (<?= $e($y['starts_on']) ?>–<?= $e($y['ends_on']) ?>)</option><?php endforeach; ?></select></label><label class="block text-sm">Term name<input required name="name" maxlength="80" placeholder="Autumn term" class="mt-1 block w-full rounded-lg border px-3 py-2"></label><div class="grid grid-cols-2 gap-3"><label class="text-sm">Starts<input required type="date" name="starts_on" class="mt-1 block w-full rounded-lg border px-2 py-2"></label><label class="text-sm">Ends<input required type="date" name="ends_on" class="mt-1 block w-full rounded-lg border px-2 py-2"></label></div><button class="rounded-lg bg-cyan-700 px-4 py-2 text-sm font-semibold text-white">Add term</button></form><div class="mt-5 space-y-2"><?php foreach($terms as $t): ?><div class="flex justify-between border-t pt-2 text-sm"><span><?= $e($t['year_name']) ?> · <strong><?= $e($t['name']) ?></strong></span><span class="text-slate-500"><?= $e($t['starts_on']) ?> – <?= $e($t['ends_on']) ?></span></div><?php endforeach; ?></div></section>
<section class="rounded-xl border bg-white p-5"><h2 class="font-semibold">Bank holidays</h2><p class="mt-1 text-sm text-slate-500">These dates should not receive scheduled teaching.</p><form method="post" action="/calendar/holiday" class="mt-4 space-y-3"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><label class="block text-sm">Holiday name<input required name="name" maxlength="120" placeholder="Christmas Day" class="mt-1 block w-full rounded-lg border px-3 py-2"></label><label class="block text-sm">Date<input required type="date" name="holiday_date" class="mt-1 block w-full rounded-lg border px-3 py-2"></label><button class="rounded-lg bg-cyan-700 px-4 py-2 text-sm font-semibold text-white">Add holiday</button></form><div class="mt-5 space-y-2"><?php foreach($holidays as $h): ?><div class="flex justify-between border-t pt-2 text-sm"><span><?= $e($h['name']) ?></span><span class="text-slate-500"><?= $e($h['holiday_date']) ?></span></div><?php endforeach; ?></div></section></div>
<section class="rounded-xl border bg-white p-5"><h2 class="font-semibold">Configured terms</h2><div class="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3"><?php foreach($terms as $t): ?><article class="rounded-lg bg-slate-50 p-3 text-sm"><div class="font-medium"><?= $e($t['year_name']) ?> · <?= $e($t['name']) ?></div><div class="mt-1 text-slate-600"><?= $e($t['starts_on']) ?> to <?= $e($t['ends_on']) ?></div></article><?php endforeach; ?></div><p class="mt-4 text-xs text-slate-500">Each course unit offering will also carry its own start and end dates, constrained to its selected academic year and term.</p></section>
<section class="rounded-xl border border-slate-200 bg-white p-5"><h2 class="font-semibold">Remove calendar entries</h2><p class="mt-1 text-sm text-slate-500">Academic years with active course offerings cannot be removed.</p><div class="mt-4 grid gap-5 lg:grid-cols-3"><div><h3 class="text-sm font-medium">Years</h3><?php foreach($years as $y): ?><form method="post" action="/calendar/delete" class="mt-2 flex items-center justify-between border-t pt-2 text-sm"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="kind" value="year"><input type="hidden" name="id" value="<?= (int)$y['id'] ?>"><span><?= $e($y['name']) ?></span><button class="text-rose-700">Remove</button></form><?php endforeach; ?></div><div><h3 class="text-sm font-medium">Terms</h3><?php foreach($terms as $t): ?><form method="post" action="/calendar/delete" class="mt-2 flex items-center justify-between border-t pt-2 text-sm"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="kind" value="term"><input type="hidden" name="id" value="<?= (int)$t['id'] ?>"><span><?= $e($t['year_name'].' · '.$t['name']) ?></span><button class="text-rose-700">Remove</button></form><?php endforeach; ?></div><div><h3 class="text-sm font-medium">Bank holidays</h3><?php foreach($holidays as $h): ?><form method="post" action="/calendar/delete" class="mt-2 flex items-center justify-between border-t pt-2 text-sm"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="kind" value="holiday"><input type="hidden" name="id" value="<?= (int)$h['id'] ?>"><span><?= $e($h['holiday_date'].' · '.$h['name']) ?></span><button class="text-rose-700">Remove</button></form><?php endforeach; ?></div></div></section>
</div></main></div></body></html>
